int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    struct usb_host_interface *iface;
    struct usb_endpoint_descriptor *ep_desc;
    int i;

    iface = port->port->config->interface->cur_altsetting;

    for (i = 0; i < iface->desc.bNumEndpoints; ++i) {
        ep_desc = &iface->endpoint[i].desc;
        if (usb_endpoint_dir_out(ep_desc) && usb_endpoint_xfer_int(ep_desc))
            break;
    }

    if (i == iface->desc.bNumEndpoints)
        return -ENODEV;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    spin_lock_init(&priv->lock);
    usb_fill_int_urb(priv->interrupt_urb, port->serial->dev,
                     usb_rcvintpipe(port->serial->dev, ep_desc->bEndpointAddress),
                     priv->interrupt_data, sizeof(priv->interrupt_data),
                     cypress_interrupt_read, priv, ep_desc->bInterval);

    priv->interrupt_urb->transfer_flags |= URB_AUTO_CLEAR_TRANSFER_BUFFER;

    if (iface->endpoint[i].extralen >= 2) {
        u8 *extra = iface->endpoint[i].extra;
        priv->pkt_size = get_unaligned_le16(extra);
    } else {
        priv->pkt_size = 64;
    }

    priv->read_urb_size = priv->pkt_size;
    priv->write_urb_size = priv->pkt_size;

    port->port->read_interval = ep_desc->bInterval;
    port->port->write_interval = ep_desc->bInterval;

    port->private = priv;

    return 0;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int i;

    /* Check for required endpoints */
    if (!port->port.open_count) {
        return -ENODEV;
    }

    /* Allocate memory for the private data structure */
    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    /* Initialize locks and FIFO buffers */
    mutex_init(&priv->mutex);
    for (i = 0; i < CY_MAX_NPORTS; ++i) {
        spin_lock_init(&priv->lock[i]);
        setup_timer(&priv->timer[i], cypress_timer, (unsigned long)port);
    }

    /* Configure packet format based on interrupt output size */
    if (port->interrupt_out_urb && port->interrupt_out_urb->ep->desc.wMaxPacketSize > 8) {
        priv->packet_format = PACKET_FORMAT_LARGE;
    } else {
        priv->packet_format = PACKET_FORMAT_SMALL;
    }

    /* Handle special cases for certain devices */
    if (port->serial->dev->descriptor.idVendor == 0x0403 && port->serial->dev->descriptor.idProduct == 0x6001) {
        priv->special_case = 1;
    }

    /* Set read/write intervals based on provided values or defaults */
    priv->read_interval = port->serial->dev->descriptor.bMaxPacketSize ? : 16;
    priv->write_interval = port->serial->dev->descriptor.bNumConfigurations ? : 8;

    /* Associate the private data with the port */
    usb_set_serial_port_data(port, priv);

    /* Set drain delay */
    priv->drain_delay = 10;

    return 0;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int endpoint;
    int i;
    int packet_size;
    int ret;

    /* Check for required endpoints */
    for (i = 0; i < USB_SERIAL_NUM_ENDPOINTS; i++) {
        if (port->port->write_urb && port->port->write_urb->ep->desc.bEndpointAddress == i) {
            endpoint = i;
            break;
        }
    }
    if (i == USB_SERIAL_NUM_ENDPOINTs)
        return -ENODEV;

    /* Allocate private data */
    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    /* Initialize locks and FIFO buffers */
    spin_lock_init(&priv->lock);
    usb_serial_init_port(port);

    /* Determine packet size based on interrupt output size */
    packet_size = usb_endpoint_maxp(port->port->write_urb->ep->desc);

    /* Handle special cases for certain devices */
    if (port->serial->dev->descriptor.idVendor == 0x0403 && port->serial->dev->descriptor.idProduct == 0x6001) {
        packet_size = 64;
    }

    /* Set read/write intervals */
    priv->write_interval = 16;
    priv->read_interval = 16;

    /* Associate private data with port */
    usb_set_serial_port_data(port, priv);

    /* Set drain delay */
    priv->drain_delay = 10;

    return 0;
}

int cypress_probe(struct usb_serial_port *port)
{
    int ret = 0;
    struct usb_endpoint_descriptor *ep;
    unsigned int read_interval = 0x10;
    unsigned int write_interval = 0x10;
    unsigned int drain_delay = 0x10;
    struct cypress_private *priv;

    ep = usb_endpoint_num_desc(port->serial->interface, USB_DIR_OUT);
    if (!ep) {
        return -ENODEV;
    }

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv) {
        return -ENOMEM;
    }

    spin_lock_init(&priv->lock);
    priv->bulk_in_size = le16_to_cpu(ep->wMaxPacketSize);
    init_usb_anchor(&priv->delayed_work);

    if (priv->bulk_in_size == 64) {
        read_interval = 0x10;
        write_interval = 0x10;
    } else {
        read_interval = 0x10;
        write_interval = 0x10;
    }

    priv->read_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!priv->read_urb) {
        ret = -ENOMEM;
        goto error;
    }

    priv->write_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!priv->write_urb) {
        ret = -ENOMEM;
        goto error;
    }

    usb_serial_set_private_data(port, priv);
    port->bulk_in_size = priv->bulk_in_size;
    port->private = priv;

    port->read_interval = read_interval;
    port->write_interval = write_interval;
    port->drain_delay = drain_delay;

    return 0;

error:
    kfree(priv);
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    int ret;
    struct usb_endpoint_descriptor *ep;
    struct cypress_private *priv;

    ep = usb_endpoint_ptr(port->port_num, USB_DIR_OUT | USB_ENDPOINT_XFER_INT);
    if (!ep) {
        return -ENODEV;
    }

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv) {
        return -ENOMEM;
    }

    spin_lock_init(&priv->lock);
    ret = usb_serial_fifo_alloc(port, &priv->bulk_in, 16 * 1024);
    if (ret < 0) {
        kfree(priv);
        return ret;
    }

    priv->packet_size = le16_to_cpu(ep->wMaxPacketSize);

    port->private_data = priv;
    port->drain_delay = 500;

    return 0;
}
